function stats(){let a=P().accounts[0],m=today().slice(0,7),y=today().slice(0,4),mt=a.transactions.filter(t=>t.date.startsWith(m)),yr=a.transactions.filter(t=>t.date.startsWith(y));return{a,mi:mt.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0),mo:mt.filter(t=>t.amount<0).reduce((s,t)=>s-t.amount,0),yi:yr.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0),yo:yr.filter(t=>t.amount<0).reduce((s,t)=>s-t.amount,0)}}function txs(list,cn=false){return list.map(t=>`<div class="tx"><div><b>${t.description}</b><small>${t.date}</small></div><b class="${t.amount>=0?'pos':'neg'}">${t.amount>=0?'+':'−'}${money(Math.abs(t.amount))}</b></div>`).join('')||`<p>${cn?'暂无记录':'No Transactions Yet'}</p>`}
