function analysis(){let a=P().accounts[0],years=[...new Set(a.transactions.map(t=>t.date.slice(0,4)))],y=years[0]||today().slice(0,4);V.innerHTML=`<div class="panel"><h2>储蓄分析</h2><select id="year">${years.map(x=>`<option>${x}</option>`).join('')||`<option>${y}</option>`}</select><div id="ana"></div></div>`;function draw(){y=$('#year').value;let ts=a.transactions.filter(t=>t.date.startsWith(y)),i=ts.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0),o=ts.filter(t=>t.amount<0).reduce((s,t)=>s-t.amount,0);$('#ana').innerHTML=`<div class="stats" style="margin-top:12px"><div class="stat"><small>全年存入</small><b>${money(i)}</b></div><div class="stat"><small>全年取出</small><b>${money(o)}</b></div><div class="stat"><small>年度净储蓄</small><b>${money(i-o)}</b></div><div class="stat"><small>当前余额</small><b>${money(a.balance)}</b></div></div>`}$('#year').onchange=draw;draw()}
function adultSettings(){V.innerHTML=`<div class="panel"><h2>设置</h2><div class="settings-actions"><button id="change" class="settings-control">修改密码</button><button id="backup" class="settings-control">导出备份</button><label class="settings-control">恢复备份<input id="restore" type="file" hidden></label><button id="delete" class="settings-control danger">删除成人账户</button></div></div><p>Version 3.0</p>`;$('#change').onclick=changePassword;$('#backup').onclick=backup;$('#restore').onchange=e=>restore(e.target.files[0]);$('#delete').onclick=()=>{if(confirm('永久删除此成人账户及所有记录？')){db.profiles=db.profiles.filter(x=>x.id!==P().id);save();profiles()}}}function changePassword(){open(`<h2>修改密码</h2><label>新 PIN</label><input id="p1" type="password" inputmode="numeric" maxlength="6"><label>确认 PIN</label><input id="p2" type="password" inputmode="numeric" maxlength="6"><button id="go" class="btn primary full submit">保存</button>`);$('#go').onclick=async()=>{if(!/^\d{4,6}$/.test($('#p1').value)||$('#p1').value!==$('#p2').value)return toast('请输入一致的 4–6 位数字 PIN');P().passwordHash=await hash($('#p1').value);save();close()}}
function accounts(){let p=P(),items=[...p.accounts,{id:'add-account',type:'add'}];V.innerHTML=`<div class="hero"><small>Combined Balance</small><div class="money">${money(total(p))}</div></div><div class="row between stack-heading"><h2>Your Accounts</h2><small id="stackCounter"></small></div><div id="accountStack" class="account-stack" tabindex="0" aria-label="Account card stack">${p.accounts.map(a=>bankCard(a,p)).join('')}<div class="cardwrap add-stack-card"><div class="balancepill invisible">$0.00</div><button type="button" id="addA" class="bankcard addcard" style="background-image:url('${img('cards','card-add-new-possibility')}')"><img src="${img('buttons','button-add-account')}" alt=""><b>Add Account</b></button></div></div><p class="stack-help">Swipe up or down to change cards. Tap the top card to open.</p>`;initAccountStack(items)}function initAccountStack(items){let stack=$('#accountStack'),wraps=[...stack.querySelectorAll('.cardwrap')],selected=0,startY=0,lastY=0,touching=false,pointerId=null,suppressClickUntil=0;function layout(animate=true){let width=stack.clientWidth,cardH=Math.min(292,width*.63),top=8,gap=Math.max(30,Math.min(48,(stack.clientHeight-cardH-18)/Math.max(1,wraps.length-1)));wraps.forEach((wrap,i)=>{let rel=(i-selected+wraps.length)%wraps.length;wrap.style.setProperty('--stack-y',top+rel*gap+'px');wrap.style.setProperty('--stack-scale',1-Math.min(rel,6)*.018);wrap.style.zIndex=String(wraps.length-rel);wrap.classList.toggle('is-front',rel===0);wrap.classList.toggle('no-animate',!animate);let button=wrap.querySelector('.bankcard');if(button)button.tabIndex=rel===0?0:-1});$('#stackCounter').textContent=selected+1+' / '+wraps.length}function move(dir){selected=(selected+dir+wraps.length)%wraps.length;layout(true);suppressClickUntil=Date.now()+420}wraps.forEach((wrap,i)=>{let card=wrap.querySelector('[data-a]');if(card)card.onclick=()=>{if(Date.now()<suppressClickUntil||!wrap.classList.contains('is-front'))return;childAccount(card.dataset.a)};let add=wrap.querySelector('#addA');if(add)add.onclick=async()=>{if(Date.now()<suppressClickUntil||!wrap.classList.contains('is-front'))return;if(await approveChild(P(),'create an account'))createChildAccount()}});stack.addEventListener('touchstart',e=>{let t=e.touches[0];if(!t)return;touching=true;startY=lastY=t.clientY},{passive:true});stack.addEventListener('touchmove',e=>{if(!touching)return;lastY=e.touches[0].clientY;if(Math.abs(lastY-startY)>10)e.preventDefault()},{passive:false});stack.addEventListener('touchend',e=>{if(!touching)return;touching=false;let t=e.changedTouches[0],dy=(t?t.clientY:lastY)-startY;if(Math.abs(dy)>=45)move(dy<0?1:-1)},{passive:false});stack.addEventListener('touchcancel',()=>touching=false);stack.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;pointerId=e.pointerId;startY=lastY=e.clientY;try{stack.setPointerCapture(pointerId)}catch{}});stack.addEventListener('pointermove',e=>{if(e.pointerId!==pointerId)return;lastY=e.clientY});stack.addEventListener('pointerup',e=>{if(e.pointerId!==pointerId)return;let dy=e.clientY-startY;try{stack.releasePointerCapture(pointerId)}catch{}pointerId=null;if(Math.abs(dy)>=45)move(dy<0?1:-1)});stack.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();move(-1)}else if(e.key==='ArrowDown'){e.preventDefault();move(1)}};layout(false);requestAnimationFrame(()=>layout(true));window.addEventListener('resize',()=>layout(false),{once:true})}function shareMarketPanel(a){let m=marketState(a);return`<div class="panel market-panel"><div class="row between"><div><h3>Share Market Simulation</h3><small>${m.label}</small></div><span class="market-dot ${m.open?'open':'closed'}"></span></div><div class="row between market-metrics"><span>Today</span><b class="${m.pct>=0?'pos':'neg'}">${m.pct>=0?'+':''}${m.pct.toFixed(2)}%</b></div><p>Updates every 10 minutes during the simulated weekday session. Daily safety limit: ±20%.</p>${m.limit?'<div class="warning">Daily simulation limit reached. Value is frozen until the next market day.</div>':''}</div>`}
function childAccount(id){aid=id;$('#back').onclick=()=>{aid=null;header(P().name,'Pocket Money Master','add');accounts()};let a=A(),p=P(),status=a.matured?' · Matured':a.bankrupt?' · Inactive':'';V.innerHTML=`<div class="hero"><small>${childType(a)}${status}</small><div class="money">${money(a.balance)}</div></div><div class="actions child-actions">${a.type==='transaction'?'<button id="add" class="action"><img src="'+img('buttons','button-add-money')+'">Add</button><button id="spend" class="action"><img src="'+img('buttons','button-spend-money')+'">Spend</button>':''}${a.type==='investment'&&a.investmentType==='shares'?`<button id="buyShares" class="action"><img src="${img('buttons','button-add-money')}">Buy Shares</button><button id="sellShares" class="action"><img src="${img('buttons','button-spend-money')}">Sell Shares</button>`:`<button id="transfer" class="action"><img src="${img('buttons','button-transfer-money')}">Transfer</button>`}<button id="details" class="action"><img src="${img('buttons','button-account-details')}">Details</button>${a.type==='savings'?'<button id="rateBtn" class="action"><b class="percent-icon">%</b>Rate</button>':''}</div>${a.type==='investment'&&a.investmentType==='shares'?shareMarketPanel(a):''}<div class="panel"><h3>Balance History · 3 Months</h3><canvas id="chart" class="chart"></canvas></div><div class="panel"><h3>Recent Transactions</h3>${txs(a.transactions)}</div>`;if($('#add'))$('#add').onclick=async()=>{if(await approveChild(P(),'add money'))childTx('add')};if($('#spend'))$('#spend').onclick=()=>childTx('spend');if($('#transfer'))$('#transfer').onclick=childTransfer;if($('#buyShares'))$('#buyShares').onclick=()=>shareTrade(a,'buy');if($('#sellShares'))$('#sellShares').onclick=()=>shareTrade(a,'sell');$('#details').onclick=()=>childDetails(a);if($('#rateBtn'))$('#rateBtn').onclick=async()=>{if(await approveChild(P(),'change the savings rate'))changeSavingsRate(a)};drawChart(a)}function childType(a){return a.type==='transaction'?'Transaction':a.type==='savings'?'Savings':a.type==='term'?'Term Deposit':(investments[a.investmentType]?.name||'Investment Type Required')}function drawChart(a){let c=$('#chart');if(!c||!a.history.length)return;let d=devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*d;c.height=h*d;let x=c.getContext('2d');x.scale(d,d);let pts=a.history.filter(p=>days(p.date,today())<=90),lo=Math.min(...pts.map(p=>p.balance)),hi=Math.max(...pts.map(p=>p.balance));if(lo===hi){lo-=100;hi+=100}x.beginPath();pts.forEach((p,i)=>{let px=12+i*(w-24)/Math.max(1,pts.length-1),py=h-18-(p.balance-lo)/(hi-lo)*(h-36);i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle='#1769f6';x.lineWidth=3;x.stroke()}function changeSavingsRate(a){open(`<h2>Change Savings Rate</h2>${rateBox(a.rate,5)}<button id="go" class="btn primary full submit">Save Rate</button>`);wireRate();$('#go').onclick=()=>{a.rate=+$('#rate').value;save();close();childAccount(a.id)}}function childDetails(a){let extra='';if(a.type==='savings')extra=`<p><b>Interest:</b> ${a.rate.toFixed(2)}% p.a., credited monthly</p>`;else if(a.type==='term')extra=`<p><b>Interest:</b> ${a.rate.toFixed(2)}% p.a.</p><p><b>Maturity:</b> ${a.maturity||'Not set'}</p><p><b>Accrued:</b> ${money(Math.round(a.accrued||0))}</p>`;else if(a.type==='investment'){let q=investments[a.investmentType];extra=q?`<p><b>Investment:</b> ${q.name}</p><p><b>Risk:</b> ${q.risk}</p><p><b>Simulation range:</b> ${a.investmentType==='shares'?'10-minute movement, daily cap ±20%':q.min+'% to +'+q.max+'% daily'}</p>`:`<div class="warning"><b>Investment type needs repair.</b><p>Select the original investment type below.</p></div>${Object.entries(investments).map(([k,v])=>`<button class="btn full repair-investment" data-repair="${k}">${v.name}</button>`).join('')}`;}else extra='<p><b>Interest:</b> 0.00% p.a.</p>';open(`<h2>Account Details</h2><p><b>Name:</b> ${a.name}</p><p><b>Type:</b> ${childType(a)}</p>${extra}${a.type!=='transaction'?'<button id="closeAccount" class="btn danger full details-close">Close Account</button>':''}`);B.querySelectorAll('[data-repair]').forEach(x=>x.onclick=async()=>{if(await approveChild(P(),'repair this investment account')){a.investmentType=x.dataset.repair;a.requiresInvestmentRepair=false;if(a.investmentType==='shares'){a.marketDay=brisbaneParts().date;a.dayOpenBalance=a.balance;a.dayNetContribution=0;a.dayMarketPct=0;a.lastMarketSlot=marketSlot()}save();close();childAccount(a.id)}});if($('#closeAccount'))$('#closeAccount').onclick=async()=>{if(await approveChild(P(),'close this account'))closeChildAccount(a)}}async function closeChildAccount(a){let p=P(),t=p.accounts.find(x=>x.type==='transaction');if(a.type==='term'&&a.active){open(`<h2>Close Term Deposit Early?</h2><div class="warning"><b>${money(Math.round(a.accrued||0))} accrued interest will be forfeited.</b><p>${money(a.balance)} will return to the Transaction Account.</p></div><button id="confirmClose" class="btn danger full">Continue</button>`);$('#confirmClose').onclick=()=>{rec(t,a.balance,'transfer','Early Closure of '+a.name);p.accounts=p.accounts.filter(x=>x.id!==a.id);save();close();aid=null;accounts()};return}if(a.balance)return toast('Transfer the full balance out first');p.accounts=p.accounts.filter(x=>x.id!==a.id);save();close();aid=null;accounts()}
function childTx(kind){open(`<h2>${kind==='add'?'Add Money':'Record Spending'}</h2>${moneyField('amount','Amount')}<label>Description</label><input id="desc"><button id="go" class="btn primary full submit">Save</button>`);wireMoney();$('#go').onclick=()=>{let a=A(),c=Math.round((+$('#amount').value||0)*100);if(!c||kind==='spend'&&c>a.balance)return toast('Check amount');rec(a,kind==='add'?c:-c,kind,$('#desc').value.trim()||kind);save();close();childAccount(a.id)}}function shareTrade(a,side){let p=P(),other=p.accounts.filter(x=>x.id!==a.id&&x.type!=='term'&&!x.bankrupt),buy=side==='buy';if(!other.length)return toast('No available account');open(`<h2>${buy?'Buy Shares':'Sell Shares'}</h2><p>${marketState(a).open?'Market Open: value continues changing every 10 minutes.':'Market Closed: value is fixed, but buying and selling remain available.'}</p><label>${buy?'From Account':'Transfer To'}</label><select id="shareOther">${other.map(x=>`<option value="${x.id}">${x.name} · ${money(x.balance)}</option>`).join('')}</select>${moneyField('shareAmount','Amount')}<button id="confirmShareTrade" class="btn primary full submit">${buy?'Confirm Purchase':'Confirm Sale'}</button>`);wireMoney();$('#confirmShareTrade').onclick=()=>{let b=p.accounts.find(x=>x.id===$('#shareOther').value),c=Math.round((+$('#shareAmount').value||0)*100);if(!c||buy&&c>b.balance||!buy&&c>a.balance)return toast('Check amount');if(a.marketDay!==brisbaneParts().date){a.marketDay=brisbaneParts().date;a.dayOpenBalance=a.balance;a.dayNetContribution=0;a.dayMarketPct=0}if(buy){rec(b,-c,'share-buy','Bought Shares · To '+a.name);rec(a,c,'share-buy','Bought Shares · From '+b.name);a.dayNetContribution=(a.dayNetContribution||0)+c}else{rec(a,-c,'share-sell','Sold Shares · To '+b.name);rec(b,c,'share-sell','Sold Shares · From '+a.name);a.dayNetContribution=(a.dayNetContribution||0)-c}save();close();childAccount(a.id)}}function childTransfer(){let a=A(),ds=P().accounts.filter(x=>x.id!==a.id&&!(x.type==='term'&&x.active)&&!x.bankrupt);if(!ds.length)return toast('No destination account');open(`<h2>Transfer</h2><select id="dest">${ds.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select>${moneyField('amount','Amount')}<button id="go" class="btn primary full submit">Transfer</button>`);wireMoney();$('#go').onclick=()=>{let c=Math.round((+$('#amount').value||0)*100),b=P().accounts.find(x=>x.id===$('#dest').value);if(!c||c>a.balance)return toast('Check amount');rec(a,-c,'transfer','Transfer to '+b.name);rec(b,c,'transfer','Transfer from '+a.name);save();close();childAccount(a.id)}}function rateBox(v,max){return`<label>Annual Interest Rate</label><div class="rate"><button data-minus>−</button><input id="rate" type="number" min="0" max="${max}" step=".1" value="${(+v).toFixed(2)}"><button data-plus>＋</button></div><input id="slider" type="range" min="0" max="${max}" step=".1" value="${v}"><p class="rate-display"><b><span id="rdisplay">${(+v).toFixed(2)}</span>% p.a.</b></p>`}function setRate(v){let r=$('#rate');v=Math.max(+r.min,Math.min(+r.max,+v||0));r.value=v.toFixed(2);$('#slider').value=v;$('#rdisplay').textContent=v.toFixed(2)}function wireRate(){if(!$('#rate'))return;$('#rate').oninput=()=>setRate($('#rate').value);$('#slider').oninput=()=>setRate($('#slider').value);$('[data-minus]').onclick=()=>setRate(+$('#rate').value-.1);$('[data-plus]').onclick=()=>setRate(+$('#rate').value+.1)}
function createChildAccount(){let card=defaultCard('savings'),kind='savings';open(`<h2>Create Account</h2><label>Account Type</label><select id="type"><option value="savings">Savings</option><option value="term">Term Deposit</option><option value="investment">Investment</option></select><label>Name</label><input id="name" value="My Savings"><div id="dynamic"></div><label>Card Design</label>${cardPicker(card)}<button id="go" class="btn primary full submit">Create</button>`);function dynamic(){kind=$('#type').value;card=defaultCard(kind);$('#name').value=kind==='savings'?'My Savings':kind==='term'?'Term Deposit':'My Investment';$('#dynamic').innerHTML=kind==='savings'?`${moneyField('amount','Initial Deposit')}${rateBox(2,5)}`:kind==='term'?`<label>Term</label><select id="term"><option value="1">1 Month · 3.00%</option><option value="3">3 Months · 4.00%</option><option value="6">6 Months · 5.00%</option><option value="12">1 Year · 8.00%</option></select>${moneyField('amount','Initial Deposit')}${rateBox(3,10)}`:`<label>Investment Type</label>${Object.entries(investments).map(([k,v],i)=>`<div data-invest="${k}" class="choice ${i?'':'selected'}"><b>${v.name}</b> <span class="badge">${v.risk}</span><p>${v.min}% to +${v.max}% daily</p></div>`).join('')}${moneyField('amount','Initial Deposit')}`;wireMoney();wireRate();if($('#term'))$('#term').onchange=()=>setRate(({1:3,3:4,6:5,12:8})[+$('#term').value]);B.querySelectorAll('[data-invest]').forEach(x=>x.onclick=()=>{B.querySelectorAll('[data-invest]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')})}$('#type').onchange=dynamic;dynamic();wireCards(v=>card=v);$('#go').onclick=()=>{let p=P(),src=p.accounts.find(x=>x.type==='transaction'),c=Math.round((+$('#amount').value||0)*100),name=$('#name').value.trim();if(!name||c>src.balance)return toast('Check account details');if(kind!=='savings'&&!c)return toast('Initial Deposit required');let a={id:uid(),type:kind,name,card,balance:0,transactions:[],history:[],created:today(),lastProcessed:today(),active:true};if(kind==='savings'){a.rate=+$('#rate').value;a.remainder=0}else if(kind==='term'){a.principal=c;a.termMonths=+$('#term').value;a.rate=+$('#rate').value;a.maturity=addMonth(today(),a.termMonths);a.accrued=0}else{a.investmentType=B.querySelector('[data-invest].selected').dataset.invest;if(a.investmentType==='shares'){a.marketDay=brisbaneParts().date;a.dayOpenBalance=c;a.dayNetContribution=0;a.dayMarketPct=0;a.lastMarketSlot=marketSlot()}}if(c){rec(src,-c,'transfer','Transfer to '+a.name);rec(a,c,'transfer','Transfer from '+src.name)}p.accounts.push(a);save();close();accounts()}}
function activity(){V.innerHTML=`<div class="panel"><h2>All Activities</h2>${txs(P().accounts.flatMap(a=>a.transactions).sort((a,b)=>b.ts-a.ts))}</div>`}function summary(){let p=P(),all=p.accounts.flatMap(a=>a.transactions.map(t=>({...t,accountType:a.type}))),received=0,spent=0,interest=0,gains=0,losses=0,saved=0;all.forEach(t=>{if(t.type==='add'&&t.amount>0)received+=t.amount;if(t.type==='spend')spent+=Math.abs(t.amount);if(t.type==='interest')interest+=t.amount;if(t.type==='investment')t.amount>=0?gains+=t.amount:losses+=Math.abs(t.amount);if(t.type==='transfer'&&t.amount>0&&['savings','term'].includes(t.accountType))saved+=t.amount});V.innerHTML=`<div class="panel"><h2>Summary</h2><div class="tx"><b>Received</b><b>${money(received)}</b></div><div class="tx"><b>Spent</b><b>${money(spent)}</b></div><div class="tx"><b>Interest</b><b>${money(interest)}</b></div><div class="tx"><b>Investment Gains</b><b>${money(gains)}</b></div><div class="tx"><b>Investment Losses</b><b>${money(losses)}</b></div><div class="tx"><b>Saved Into Savings/Term</b><b>${money(saved)}</b></div><div class="tx"><b>Combined Balance</b><b>${money(total(p))}</b></div></div>`}
function childSettings(){let p=P();V.innerHTML=`<div class="panel"><h2>Profile Settings</h2><div class="settings-actions"><button id="changeParentPin" class="settings-control">Change Parent PIN</button><button id="backup" class="settings-control">Export Backup</button><button id="delete" class="settings-control danger">Delete Profile</button></div></div><div class="panel"><h3>Profile Avatar</h3>${avatarPicker(p.avatar)}</div><p>Version 3.0</p>`;$('#changeParentPin').onclick=async()=>{if(await approveChild(p,'change the Parent PIN')){open(`<h2>Change Parent PIN</h2><label>New PIN</label><input id="newPin1" type="password" inputmode="numeric" maxlength="6"><label>Confirm PIN</label><input id="newPin2" type="password" inputmode="numeric" maxlength="6"><button id="saveNewPin" class="btn primary full submit">Save PIN</button>`);$('#saveNewPin').onclick=async()=>{let v=$('#newPin1').value;if(!/^\d{4,6}$/.test(v)||v!==$('#newPin2').value)return toast('Enter matching 4–6 digit PINs');p.pinHash=await hash(v);p.pinEnabled=true;save();close()}}};$('#backup').onclick=backup;V.querySelectorAll('[data-avatar]').forEach(x=>x.onclick=()=>{V.querySelectorAll('[data-avatar]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');p.avatar=x.dataset.avatar;save()});$('#delete').onclick=async()=>{if(await approveChild(p,'delete this profile')&&confirm('Delete this profile and all records?')){db.profiles=db.profiles.filter(x=>x.id!==p.id);save();profiles()}}}
function refreshFinancialData(){let p=P();if(!p||p.profileType==='adult')return;let currentAid=aid;processChild(p);if(currentAid&&p.accounts.some(a=>a.id===currentAid))childAccount(currentAid);else if(tab==='accounts')accounts()}function backup(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`pocket-money-master-${today()}.json`;a.click()}async function restore(f){try{let d=JSON.parse(await f.text());if(!d.profiles)throw 0;db=d;save();close();profiles()}catch{toast('Invalid backup')}}function init(){V=$('#view');M=$('#modal');B=$('#mb');db=load();$('#x').onclick=close;M.onclick=e=>{if(e.target===M)close()};$('#nav').onclick=e=>{let b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;render()};document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshFinancialData()});window.addEventListener('pageshow',refreshFinancialData);window.addEventListener('focus',refreshFinancialData);setTimeout(()=>{$('#splash').remove();$('#app').classList.remove('hidden');profiles()},2000)}window.addEventListener('DOMContentLoaded',init);

/* ===== Pocket Money Master V4.2 integrated market architecture ===== */
