const PMM_VERSION='4.2',MARKET_TYPES=['bonds','fund','property','shares'];
const MARKET_DEFAULTS={bonds:{range:[-1,2],volatility:'low',stable:.02},fund:{range:[-5,6],volatility:'medium',stable:.05},property:{range:[-8,8],volatility:'medium',stable:.08},shares:{range:[-15,15],volatility:'medium',stable:.10}};
function newMarket(type){let m={type,index:10000,lastProcessed:today(),dailyRates:{},scenario:null,defaultProtection:50};m.scenario=randomMarketScenario(m);return m}
function marketScenario(m,o={}){return{length:+o.length||28,target:Number.isFinite(+o.target)?Math.max(-50,Math.min(50,+o.target)):0,volatility:o.volatility||MARKET_DEFAULTS[m.type].volatility,after:o.after||'random',mode:o.mode||'scenario',startDate:today(),startIndex:+m.index||10000,random:!!o.random,downStreak:+o.downStreak||0}}
function randomMarketScenario(m){let old=m.scenario||{},len=[7,14,28][Math.floor(Math.random()*3)],r=Math.random(),dir=(+old.downStreak||0)>=2?(r<.65?'up':'stable'):(r<.45?'up':r<.75?'down':'stable'),base=MARKET_DEFAULTS[m.type].range,f=len/28,target=dir==='stable'?0:dir==='up'?+(Math.random()*Math.max(.1,base[1]*f)).toFixed(1):-+(Math.random()*Math.max(.1,Math.abs(base[0]*f))).toFixed(1);return marketScenario(m,{length:len,target,volatility:['low','medium','high'][Math.floor(Math.random()*3)],after:'random',random:true,downStreak:dir==='down'?(+old.downStreak||0)+1:0})}
function ensureMarkets(p){if(p.profileType==='adult')return;p.markets=p.markets||{};MARKET_TYPES.forEach(type=>{let m=p.markets[type];if(!m){let account=p.accounts.find(a=>a.type==='investment'&&a.investmentType===type);m=p.markets[type]=newMarket(type);if(account?.scenario){m.scenario={...m.scenario,...account.scenario,startDate:account.scenario.startDate||today(),startIndex:m.index}}}m.type=type;m.index=Number.isFinite(+m.index)?+m.index:10000;m.lastProcessed=m.lastProcessed||today();m.dailyRates=m.dailyRates||{};m.defaultProtection=m.defaultProtection==='off'?'off':Math.max(1,Math.min(99,+m.defaultProtection||50));if(!m.scenario)m.scenario=randomMarketScenario(m)})}
function activeScenario(m,date=today()){let s=m.scenario;if(s.mode==='steady'||days(s.startDate,date)<s.length)return s;if(s.after==='repeat')m.scenario=marketScenario(m,{length:s.length,target:s.target,volatility:s.volatility,after:'repeat',downStreak:s.target<0?s.downStreak+1:0});else if(s.after==='random')m.scenario=randomMarketScenario(m);else m.scenario=marketScenario(m,{length:28,target:0,volatility:'low',after:'steady',mode:'steady'});return m.scenario}
function marketDailyRate(m,date){if(Number.isFinite(+m.dailyRates[date]))return +m.dailyRates[date];let s=activeScenario(m,date),rate;if(s.mode==='steady'){rate=(Math.random()*2-1)*MARKET_DEFAULTS[m.type].stable}else{let elapsed=Math.min(s.length,Math.max(0,days(s.startDate,date))+1),expected=s.target*elapsed/s.length,actual=s.startIndex?100*(m.index-s.startIndex)/s.startIndex:0,base=s.target/s.length,r=MARKET_DEFAULTS[m.type].range,cap=Math.max(.08,Math.max(Math.abs(r[0]),Math.abs(r[1]))/28*1.8),noise=normalRandom()*({low:.18,medium:.42,high:.85}[s.volatility]||.42)*cap;rate=Math.max(-cap*2,Math.min(cap*2,base+(expected-actual)*.28+noise))}m.dailyRates[date]=+rate.toFixed(4);return m.dailyRates[date]}
function processMarkets(p){ensureMarkets(p);MARKET_TYPES.forEach(type=>{let m=p.markets[type],n=Math.max(0,days(m.lastProcessed,today()));for(let i=1;i<=n;i++){let date=addDay(m.lastProcessed,i),rate=marketDailyRate(m,date);m.index=Math.max(1,Math.round(m.index*(1+rate/100)))}m.lastProcessed=today();let keys=Object.keys(m.dailyRates).sort();keys.slice(0,Math.max(0,keys.length-120)).forEach(k=>delete m.dailyRates[k])})}
function accountProtection(a,m){let value=a.lossProtection===undefined?m.defaultProtection:a.lossProtection;return value==='off'?'off':Math.max(1,Math.min(99,+value||50))}
function safeInvestmentChange(a,m,c){let protection=accountProtection(a,m);if(protection==='off'||c>=0)return c;let base=Number.isFinite(+a.protectedBase)?+a.protectedBase:+a.balance||0;return Math.max(c,Math.round(base*protection/100)-a.balance)}
function investmentSettlement(a,m,date,rate){let c=safeInvestmentChange(a,m,Math.round(a.balance*rate/100));if(!c)return;rec(a,c,'investment',(investments[a.investmentType]?.name||'Investment')+' Daily Settlement · '+(rate>=0?'+':'')+rate.toFixed(2)+'%',date)}
