save=function(){db.version=PMM_VERSION;localStorage.setItem(K,JSON.stringify(db))};
processChild=function(p){ensureMarkets(p);processMarkets(p);p.accounts.forEach(a=>{let start=a.lastProcessed||a.created||today(),n=Math.max(0,days(start,today()));if(a.type==='savings')for(let i=1;i<=n;i++){let date=addDay(start,i);a.remainder=(a.remainder||0)+a.balance*(a.rate/100)/365;if(date===monthEnd(date)){let credit=Math.floor(a.remainder);a.remainder-=credit;if(credit)rec(a,credit,'interest','Monthly Savings Interest',date)}}if(a.type==='term'&&a.active){a.accrued=(a.accrued||0)+n*(a.principal||a.balance)*(a.rate/100)/365;if(a.maturity&&today()>=a.maturity){let credit=Math.round(a.accrued);a.accrued=0;a.active=false;a.matured=true;if(credit)rec(a,credit,'interest','Term Deposit Interest at Maturity',today())}}if(a.type==='investment'&&a.active&&a.investmentType!=='shares'){let m=p.markets[a.investmentType];for(let i=1;i<=n;i++){let date=addDay(start,i);investmentSettlement(a,m,date,marketDailyRate(m,date))}}a.lastProcessed=today();if(a.type==='investment'&&a.investmentType==='shares'&&a.active)processShareMarket(a)});save()};
processShareMarket=function(a,now=Date.now()){let p=P(),m=p.markets.shares,current=marketSlot(now);if(a.lastMarketSlot==null){a.lastMarketSlot=current;save();return 0}let count=0;for(let slot=Math.max(a.lastMarketSlot+1,current-144*31);slot<=current;slot++){let ms=slot*600000;if(!isMarketMoment(ms))continue;let bp=brisbaneParts(ms);if(a.marketDay!==bp.date){if(a.marketDay&&a.v40DayChange){let rate=a.v40DayOpen?100*a.v40DayChange/a.v40DayOpen:0;a.transactions.unshift({id:uid(),date:a.marketDay,ts:new Date(a.marketDay+'T23:59:00').getTime(),amount:a.v40DayChange,type:'investment',description:'Share Market Daily Settlement · '+(rate>=0?'+':'')+rate.toFixed(2)+'%',balance:a.balance});a.v40DayChange=0}a.marketDay=bp.date;a.v40DayOpen=a.balance}let daily=marketDailyRate(m,bp.date),slotRate=daily/18,change=safeInvestmentChange(a,m,Math.round(a.balance*slotRate/100));a.balance+=change;a.v40DayChange=(a.v40DayChange||0)+change;if(change){a.history.push({date:bp.date,balance:a.balance});count++}}a.dayMarketPct=a.v40DayOpen?100*(a.v40DayChange||0)/a.v40DayOpen:0;a.lastMarketSlot=current;save();return count};
function marketNewsKey(m){let t=activeScenario(m).mode==='steady'?0:activeScenario(m).target;return t>1?'positive':t<-1?'negative':'stable'}
function currentStory(type){let p=P();ensureMarkets(p);let d=PMM_NEWS_DATA[type],s=d.stories[marketNewsKey(p.markets[type])];return{d,s}}
function news(){window.scrollTo(0,0);V.innerHTML=`<div class="panel"><h2>Market News</h2><p>Read the latest reports and look for clues before you invest.</p></div>${MARKET_TYPES.map(type=>{let{d,s}=currentStory(type);return`<button class="news-card" data-story="${type}"><h3>${d.label}</h3><small>Risk Level: ${d.risk}</small><h4>${s.headline}</h4><p>${s.preview}</p><b class="read-more">Read Full Story ›</b></button>`}).join('')}<p class="simulation-note">${PMM_NEWS_DATA.disclaimer}</p>`;V.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>fullNews(b.dataset.story))}
