function shareLiveStore(m,date){m.live10=m.live10||{};if(!m.live10[date])m.live10[date]=[];return m.live10[date]}
function addShareLivePoint(m,date,slot,rate,index){let list=shareLiveStore(m,date),time=brisbaneParts(slot*600000),label=String(time.hour).padStart(2,'0')+':'+String(time.minute).padStart(2,'0');if(!list.some(x=>x.slot===slot))list.push({slot,time:label,rate:+rate.toFixed(4),index:+index.toFixed(2)});list.sort((a,b)=>a.slot-b.slot);if(list.length>36)list.splice(0,list.length-36)}
function closeShareDay(a,date){if(!a.v41DayChange&&!a.v41DaySettled)return;let amount=+a.v41DayChange||0,rate=a.v41DayOpen?100*amount/a.v41DayOpen:0;if(!a.v41DaySettled){a.transactions.unshift({id:uid(),date,ts:new Date(date+'T23:59:00').getTime(),amount,type:'investment',description:'Share Market Daily Settlement · '+(rate>=0?'+':'')+rate.toFixed(2)+'%',balance:a.balance});a.v41DaySettled=true}a.v41DayChange=0}
processShareMarket=function(a,now=Date.now()){let p=P(),m=p.markets.shares,current=marketSlot(now);m.live10=m.live10||{};if(a.lastMarketSlot==null){a.lastMarketSlot=current;save();return 0}let count=0;for(let slot=Math.max(a.lastMarketSlot+1,current-144*31);slot<=current;slot++){let ms=slot*600000;if(!isMarketMoment(ms))continue;let bp=brisbaneParts(ms);if(a.marketDay!==bp.date){if(a.marketDay)closeShareDay(a,a.marketDay);a.marketDay=bp.date;a.v41DayOpen=a.balance;a.v41DayChange=0;a.v41DaySettled=false;a.v41Remainder=0}let daily=marketDailyRate(m,bp.date),slotRate=daily/18;m.shareLiveIndex=Number.isFinite(+m.shareLiveIndex)?+m.shareLiveIndex:100;m.shareLiveIndex*=1+slotRate/100;addShareLivePoint(m,bp.date,slot,slotRate,m.shareLiveIndex);let raw=a.balance*slotRate/100+(+a.v41Remainder||0),change=raw<0?Math.ceil(raw):Math.floor(raw);a.v41Remainder=raw-change;change=safeInvestmentChange(a,m,change);if(change){a.balance+=change;a.v41DayChange=(a.v41DayChange||0)+change;a.history.push({date:bp.date,balance:a.balance});count++}}let bp=brisbaneParts(now),minutes=bp.hour*60+bp.minute;if(a.marketDay===bp.date&&minutes>=1080)closeShareDay(a,a.marketDay);a.dayMarketPct=a.v41DayOpen?100*((a.balance-a.v41DayOpen)/a.v41DayOpen):0;a.lastMarketSlot=current;let daysKept=Object.keys(m.live10).sort();daysKept.slice(0,Math.max(0,daysKept.length-7)).forEach(d=>delete m.live10[d]);save();return count};
function shareTrendSvg(points){if(!points.length)return'<p class="muted">The next 10-minute market update will appear here.</p>';let w=320,h=120,values=points.map(p=>p.index),lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo-=.1;hi+=.1}let coords=points.map((p,i)=>[(i/(Math.max(1,points.length-1)))*(w-20)+10,h-12-(p.index-lo)/(hi-lo)*(h-24)]),line=coords.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');return`<svg viewBox="0 0 ${w} ${h}" class="live-chart" role="img" aria-label="Ten-minute share market trend"><path d="${line}" fill="none" stroke="#1769f6" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
shareMarketPanel=function(a){let m=P().markets.shares,state=marketState(a),points=(m.live10?.[today()]||[]),last=points.at(-1),recent=points.slice(-6).reverse();return`<div class="panel market-panel"><div class="row between"><div><h3>Live 10-Minute Trend</h3><small>${state.label}</small></div><span class="market-dot ${state.open?'open':'closed'}"></span></div><div class="row between market-metrics"><span>Today</span><b class="${a.dayMarketPct>=0?'pos':'neg'}">${a.dayMarketPct>=0?'+':''}${(+a.dayMarketPct||0).toFixed(2)}%</b></div>${shareTrendSvg(points)}<div class="row between"><small>Last Update</small><b>${last?.time||'Waiting'}</b></div><div class="live-list">${recent.map(x=>`<div><span>${x.time}</span><b class="${x.rate>=0?'pos':'neg'}">${x.rate>=0?'+':''}${x.rate.toFixed(3)}%</b></div>`).join('')}</div><p>Market movement is calculated every 10 minutes during the weekday session. A single Daily Settlement is added to Recent Transactions after the market closes.</p></div>`};
summary=function(){let p=P(),all=p.accounts.flatMap(a=>a.transactions.map(t=>({...t,accountType:a.type}))),received=0,spent=0,interest=0,netInvestment=0;all.forEach(t=>{if(t.type==='add'&&t.amount>0)received+=t.amount;if(t.type==='spend')spent+=Math.abs(t.amount);if(t.type==='interest')interest+=t.amount;if(t.type==='investment')netInvestment+=t.amount});let groups={transaction:0,savings:0,term:0,investment:0};p.accounts.forEach(a=>groups[a.type]=(groups[a.type]||0)+a.balance);let totalBalance=total(p),rows=[['Spending Money',groups.transaction],['Savings',groups.savings],['Term Deposits',groups.term],['Investments',groups.investment]];V.innerHTML=`<div class="panel"><h2>Summary</h2><h3>Money Activity</h3><div class="tx"><b>Money Received</b><b>${money(received)}</b></div><div class="tx"><b>Money Spent</b><b>${money(spent)}</b></div><div class="tx"><b>Net Cash Flow</b><b class="${received-spent>=0?'pos':'neg'}">${money(received-spent)}</b></div><h3>Earnings and Investment</h3><div class="tx"><b>Interest Earned</b><b>${money(interest)}</b></div><div class="tx"><b>Net Investment Result</b><b class="${netInvestment>=0?'pos':'neg'}">${netInvestment>=0?'+':'−'}${money(Math.abs(netInvestment))}</b></div></div><div class="panel"><div class="row between"><h3>Current Money</h3><b>${money(totalBalance)}</b></div>${rows.map(row=>{let percent=totalBalance?row[1]/totalBalance*100:0;return`<div class="allocation"><div class="row between"><span>${row[0]}</span><b>${percent.toFixed(1)}% · ${money(row[1])}</b></div><div class="allocation-track"><i style="width:${Math.max(0,Math.min(100,percent))}%"></i></div></div>`}).join('')}</div>`};

/* ===== Pocket Money Master V4.2 variable intraday movement and dated news ===== */
function shareCategory(m){let s=activeScenario(m),equivalent=s.mode==='steady'?0:(+s.target||0)*28/Math.max(1,+s.length||28);if(equivalent>8)return'largeRise';if(equivalent>1)return'smallRise';if(equivalent<-8)return'largeFall';if(equivalent<-1)return'smallFall';return'stable'}
function newsSignature(m){let s=activeScenario(m);return[shareCategory(m),s.startDate,s.length,s.target,s.volatility,s.after].join('|')}
function chooseNewsIndex(count,current,recent=[]){let choices=Array.from({length:count},(_,i)=>i).filter(i=>i!==current&&!recent.includes(i));if(!choices.length)choices=Array.from({length:count},(_,i)=>i).filter(i=>i!==current);return choices[Math.floor(Math.random()*choices.length)]??0}
function ensureShareNews(p,force=false){ensureMarkets(p);let m=p.markets.shares,cat=shareCategory(m),sig=newsSignature(m),n=m.news||{},age=n.publishedDate?days(n.publishedDate,today()):999,changed=n.signature!==sig||n.category!==cat;if(force||changed||age>=2||!Number.isInteger(n.index)){let stories=PMM_NEWS_DATA.shareStories[cat],recent=Array.isArray(n.recent)?n.recent:[],index=chooseNewsIndex(stories.length,n.index,recent);m.news={category:cat,index,publishedDate:today(),signature:sig,recent:[index,...recent.filter(x=>x!==index)].slice(0,3)}}return m.news}
function shareStoryData(p){let n=ensureShareNews(p),raw=PMM_NEWS_DATA.shareStories[n.category][n.index];return{d:PMM_NEWS_DATA.shares,s:{headline:raw[0],preview:raw[1],paragraphs:raw.slice(2,-1),think:raw.at(-1)},publishedDate:n.publishedDate}}
function effectiveMarketStory(type){if(type==='shares')return shareStoryData(P());let d=PMM_NEWS_DATA[type],m=P().markets[type],key=marketNewsKey(m),fallback={headline:`${d.label} Market Update`,preview:'Investors are reviewing the latest information before making a decision.',paragraphs:['The market is being guided by the current scenario. Prices may change while investors respond to new information.'],think:'What clues would help you make a careful choice?'};return{d,s:(d.stories?.[key]||fallback),publishedDate:today()}}
currentStory=function(type){return effectiveMarketStory(type)};
news=function(){ensureShareNews(P());window.scrollTo(0,0);V.innerHTML=`<div class="panel"><h2>Market News</h2><p>Read the latest reports and look for clues before you invest.</p></div>${MARKET_TYPES.map(type=>{let{d,s,publishedDate}=effectiveMarketStory(type);return`<button class="news-card" data-story="${type}"><h3>${d.label}</h3><small>Risk Level: ${d.risk} · Updated ${publishedDate}</small><h4>${s.headline}</h4><p>${s.preview}</p><b class="read-more">Read Full Story ›</b></button>`}).join('')}<p class="simulation-note">${PMM_NEWS_DATA.disclaimer}</p>`;V.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>fullNews(b.dataset.story));save()};
fullNews=function(type){let{d,s,publishedDate}=effectiveMarketStory(type);V.innerHTML=`<button id="newsBack" class="btn">‹ Back to News</button><article class="full-news panel"><small>Updated ${publishedDate}</small><h2>${s.headline}</h2><p class="news-lead">${s.preview}</p>${s.paragraphs.map(x=>`<p>${x}</p>`).join('')}<div class="think"><b>Think About It</b><p>${s.think}</p></div></article><p class="simulation-note">${PMM_NEWS_DATA.disclaimer}</p>`;$('#newsBack').onclick=news;window.scrollTo(0,0)};
function slotVolatility(s){return{low:.30,medium:.75,high:1.35}[s.volatility]||.75}
function makeDailySlotPlan(m,date){m.slotPlans=m.slotPlans||{};if(m.slotPlans[date])return m.slotPlans[date];let s=activeScenario(m,date),daily=marketDailyRate(m,date),weights=[],vol=slotVolatility(s);for(let i=0;i<18;i++){let v=1+normalRandom()*vol;if(Math.random()<.22)v*=-.45-Math.random()*.75;weights.push(v)}let sum=weights.reduce((a,b)=>a+b,0);if(Math.abs(sum)<.15){weights[0]+=sum>=0?1:-1;sum=weights.reduce((a,b)=>a+b,0)}let rates=weights.map(w=>daily*w/sum),current=rates.reduce((a,b)=>a+b,0),diff=daily-current;rates[rates.length-1]+=diff;m.slotPlans[date]=rates.map(x=>+x.toFixed(5));return m.slotPlans[date]}
processShareMarket=function(a,now=Date.now()){let p=P(),m=p.markets.shares,current=marketSlot(now);m.live10=m.live10||{};if(a.lastMarketSlot==null){a.lastMarketSlot=current;save();return 0}let count=0;for(let slot=Math.max(a.lastMarketSlot+1,current-144*31);slot<=current;slot++){let ms=slot*600000;if(!isMarketMoment(ms))continue;let bp=brisbaneParts(ms);if(a.marketDay!==bp.date){if(a.marketDay)closeShareDay(a,a.marketDay);a.marketDay=bp.date;a.v41DayOpen=a.balance;a.v41DayChange=0;a.v41DaySettled=false;a.v41Remainder=0}let slotInDay=(bp.hour*60+bp.minute-900)/10,plan=makeDailySlotPlan(m,bp.date),slotRate=plan[Math.max(0,Math.min(17,slotInDay))]??0;m.shareLiveIndex=Number.isFinite(+m.shareLiveIndex)?+m.shareLiveIndex:100;m.shareLiveIndex*=1+slotRate/100;addShareLivePoint(m,bp.date,slot,slotRate,m.shareLiveIndex);let raw=a.balance*slotRate/100+(+a.v41Remainder||0),change=raw<0?Math.ceil(raw):Math.floor(raw);a.v41Remainder=raw-change;change=safeInvestmentChange(a,m,change);if(change){a.balance+=change;a.v41DayChange=(a.v41DayChange||0)+change;a.history.push({date:bp.date,balance:a.balance});count++}}let bp=brisbaneParts(now),minutes=bp.hour*60+bp.minute;if(a.marketDay===bp.date&&minutes>=1080)closeShareDay(a,a.marketDay);a.dayMarketPct=a.v41DayOpen?100*((a.balance-a.v41DayOpen)/a.v41DayOpen):0;a.lastMarketSlot=current;Object.keys(m.live10).sort().slice(0,-7).forEach(d=>delete m.live10[d]);Object.keys(m.slotPlans||{}).sort().slice(0,-7).forEach(d=>delete m.slotPlans[d]);save();return count};
const parentControl42=parentControl;parentControl=function(){parentControl42();let saveButton=$('#saveMarket');if(saveButton){let original=saveButton.onclick;saveButton.onclick=()=>{original();setTimeout(()=>{ensureShareNews(P(),true);save()},0)}}};
